class HalfbandCoefficientBank:
    def __init__(self):
        self.reset()

    def reset(self):
        pass

    def process(self,in_m,in_transition):
        status=1
        length=0
        coefficients=0
        if 1<=in_m and in_m<=4:
            status=0
            length=4*in_m+1
            coefficients=BANK[(in_m-1)*16+in_transition]
        return {"out_status":status,"out_length":length,"out_coefficients":coefficients}
